static const int peter_pray_off[33] = {
    0,792,1584,2382,3180,3978,4758,5562,6363,7173,7998,8844,9687,10530,11370,12210,13047,13896,14745,15591,16440,17256,18072,18876,19677,20451,21243,22041,22839,23637,24417,25191,25962
};


static void
peter_unpack(const unsigned char *blob, const int *off, int frame,
             uchar ch[24][80], uchar co[24][80])
{
    int i = off[frame];
    int end = off[frame + 1];
    int pos = 0;

    while (i + 2 < end && pos < PETER_CELLS) {
        int n = blob[i];
        int glyph = blob[i + 1];
        int color = blob[i + 2];

        i += 3;
        while (n-- > 0 && pos < PETER_CELLS) {
            ch[pos / 80][pos % 80] = (uchar) glyph;
            co[pos / 80][pos % 80] = (uchar) color;
            pos++;
        }
    }
    while (pos < PETER_CELLS) {
        ch[pos / 80][pos % 80] = ' ';
        co[pos / 80][pos % 80] = CLR_BLACK;
        pos++;
    }
}

void
peter_scene_cells(int scene, int frame, uchar ch[24][80], uchar co[24][80])
{
    if (scene == PETER_SCENE_PRAY) {
        if (frame < 0 || frame >= PETER_PRAY_FRAMES)
            frame = 0;
        peter_unpack(peter_pray_blob, peter_pray_off, frame, ch, co);
    } else {
        if (frame < 0 || frame >= PETER_READ_FRAMES)
            frame = 0;
        peter_unpack(peter_read_blob, peter_read_off, frame, ch, co);
    }
}
